  isSourceOrGenerationDevice(d){
    if(!d||typeof d!=='object')return false;
    if(d.hybrid_inverter===true)return true;
    const type=String(d.type||'').trim().toLowerCase().replaceAll('-','_').replaceAll(' ','_');
    const role=String(d.role||'').trim().toLowerCase().replaceAll('-','_').replaceAll(' ','_');
    const category=String(d.category||'').trim().toLowerCase().replaceAll('-','_').replaceAll(' ','_');
    const explicitSourceTypes=new Set(['solar','pv','solar_inverter','pv_inverter','inverter','hybrid_inverter','battery_inverter','generator','wind','wind_turbine','grid','grid_meter','smart_meter','energy_meter']);
    if(explicitSourceTypes.has(type)||explicitSourceTypes.has(role)||explicitSourceTypes.has(category))return true;
    const identity=[d.name,d.friendly_name,d.manufacturer,d.model].filter(Boolean).join(' ').toLowerCase();
    if(/\bfronius\b|\binverter\b|\bphotovoltaic\b|\bpv inverter\b|\bsolar inverter\b|\bgrid meter\b|\bsmart meter\b/.test(identity))return true;
    const mapped=[d.power_entity,d.energy_entity].filter(Boolean).join(' ').toLowerCase();
    if(/(?:^|[._-])(solar|pv|inverter|grid_meter|smart_meter)(?:[._-]|$)/.test(mapped))return true;
    return false;
  }

  analyticsDeviceRows(period='today'){
    const attrs=this.s('sensor.aion_ems_zeus_device_analytics')?.attributes||{},devices=Array.isArray(attrs.devices)?attrs.devices:[];
    const key=({today:'energy_today_kwh',week:'energy_week_kwh',month:'energy_month_kwh',year:'energy_year_kwh',total:'energy_total_kwh'})[period]||'energy_today_kwh';
    return devices
      .filter(d=>!this.isSourceOrGenerationDevice(d))
      .map(d=>({...d,energy_kwh:Math.max(0,Number(d[key]??d.energy_kwh??0)||0)}))
      .filter(d=>d.energy_kwh>0)
      .sort((a,b)=>b.energy_kwh-a.energy_kwh);
  }

  navigationSections(){return [
    {id:'statistics',label:'Zeus Intelligence',icon:'mdi:brain',pages:['intelligence_center','device_intelligence','mission_memory']},
    {id:'status',label:'System',icon:'mdi:cog-outline',pages:['knowledge','health','system_health','planning_results','planning_learning','planning_behavior']},
    {id:'system',label:'Manage',icon:'mdi:cog-outline',pages:['settings','device_manager','registered_devices','discovery','rooms_groups','sources']}
  ];}
  resolvePageDefinition(pageId){
    const registry=this.pageRegistry();let id=pageId||'daily_report',seen=new Set();
    while(registry[id]?.alias&&!seen.has(id)){seen.add(id);id=registry[id].alias;}
    return {id,definition:registry[id]||null};
  }
  rememberMobilePage(targetPage){
    const target=this.resolvePageDefinition(targetPage).id,current=this.resolvePageDefinition(this._page).id;
    if(!target||target===current||this._page==='kiosk'||this._dedicatedKiosk)return;
    const stack=this._mobilePageHistory||[];
    if(stack[stack.length-1]!==this._page)stack.push(this._page);
    this._mobilePageHistory=stack.slice(-24);
  }
  mobileBack(){
    const stack=this._mobilePageHistory||[];
    let previous='';
    while(stack.length&&!previous){const candidate=stack.pop();if(candidate&&this.resolvePageDefinition(candidate).id!==this.resolvePageDefinition(this._page).id)previous=candidate;}
    this._mobilePageHistory=stack;
    if(!previous)return false;
    this._page=previous;this._mobileNavOpen=false;
    try{localStorage.setItem('aion_zeus_page',this._page);}catch(_e){}
    this.render();
    requestAnimationFrame(()=>{const content=this.querySelector('.content');if(content)content.scrollTop=this._contentScrollByPage.get(this._page)||0;});
    return true;
  }
  exitToHomeAssistant(){
    this._mobileNavOpen=false;
    const target='/lovelace';
    try{
      window.history.pushState(null,'',target);
      window.dispatchEvent(new Event('location-changed'));
      return true;
    }catch(_e){
      try{window.location.assign(target);}catch(_ignored){}
      return false;
    }
  }
  renderRegisteredPage(pageId=this._page){
    const resolved=this.resolvePageDefinition(pageId),definition=resolved.definition;
    if(!definition)return this.pageContractError(pageId,'Page is not registered');
    const renderer=this[definition.renderer];
    if(typeof renderer!=='function')return this.pageContractError(pageId,`Renderer ${definition.renderer} is unavailable`);
    const missingHelpers=(definition.requires||[]).filter(name=>typeof this[name]!=='function');
    if(missingHelpers.length)return this.pageContractError(pageId,`Required page helper${missingHelpers.length===1?'':'s'} unavailable: ${missingHelpers.join(', ')}`);
    try{return renderer.apply(this,definition.args||[]);}catch(error){console.error('[AION EMS Zeus] Page render failed',pageId,error);return this.pageContractError(pageId,error?.message||String(error));}
  }
  pageContractError(pageId,reason){return `<section class="page"><article class="panel page-error"><ha-icon icon="mdi:alert-circle-outline"></ha-icon><h1>This page could not load</h1><p>${this.esc(reason)}</p><small>Page: ${this.esc(pageId)}</small><div><button type="button" data-page="daily_report" class="primary-button">Open Welcome</button><button type="button" data-page="system_health">Open Diagnostics</button></div></article></section>`;}
  validatePageContracts(){
    const registry=this.pageRegistry(),issues=[];
    for(const [id,definition] of Object.entries(registry)){
      if(definition.alias){if(!registry[definition.alias])issues.push(`${id}: missing alias target ${definition.alias}`);continue;}
      if(!definition.renderer)issues.push(`${id}: missing renderer declaration`);
      else if(typeof this[definition.renderer]!=='function')issues.push(`${id}: missing method ${definition.renderer}`);
      for(const helper of definition.requires||[])if(typeof this[helper]!=='function')issues.push(`${id}: missing helper ${helper}`);
    }
    for(const section of this.navigationSections())for(const id of section.pages)if(!registry[id])issues.push(`${section.id}: unregistered page ${id}`);
    return issues;
  }
  /* ENERGY STATUS LOCKED — user-approved; change only for explicit bug fix/request. */
  energyStatusPage(){
    const solar=this.solarPage();
    const battery=this.hasBattery()?this.batteryStatisticsPage():'';
    const grid=this.gridStatisticsPage();
    const embed=x=>String(x||'').replace(/^<section class="page([^"]*)">/,(_m,classes)=>`<section class="embedded-page${classes}">`);
    return `<section style="padding-top:18px" class="page consolidated-energy-page"><div class="page-head"><div><span>ENERGY · STATUS</span><h1>Status</h1><p>Solar, battery and grid status together in one place.</p></div></div><div class="consolidated-page-stack">${embed(solar)}${battery?embed(battery):''}${embed(grid)}</div></section>`;
  }
