    const sr=Number(this.s('sensor.aion_ems_zeus_battery_soc')?.state),soc=Number.isFinite(sr)?sr:null;
    const tSolar=Math.max(0,n(today.solar_energy_kwh)),tHome=Math.max(0,n(today.house_energy_kwh)),tImp=Math.max(0,n(today.grid_import_energy_kwh)),tExp=Math.max(0,n(today.grid_export_energy_kwh)),tCharge=Math.max(0,n(today.battery_charge_energy_kwh)),tDischarge=Math.max(0,n(today.battery_discharge_energy_kwh));
