    const fmt=(v,key)=>!Number.isFinite(v)?'—':key==='self_sufficiency'?`${v.toFixed(1)}%`:this.energyDisplay(v),summary=(key,x)=>{const st=stats(x),m=meta[key];if(!st)return `<div class="hee-summary-card" style="--hee-metric-color:${m[3]}"><ha-icon icon="${m[1]}"></ha-icon><span>${m[0]}</span><strong>No measured data</strong><small>Missing evidence is not zero.</small></div>`;return `<div class="hee-summary-card" style="--hee-metric-color:${m[3]}"><ha-icon icon="${m[1]}"></ha-icon><span>${m[0]}</span><strong>${key==='self_sufficiency'?`${st.avg.toFixed(1)}% avg`:this.energyDisplay(st.total)}</strong><small>Average ${fmt(st.avg,key)} · Min ${fmt(st.min,key)} · Max ${fmt(st.max,key)}</small></div>`;};
