    const lines=(vals,key,cls)=>{const groups=[];let group=[];vals.forEach((v,i)=>{const p=point(v,i,key),gap=i>0&&selDates[i-1]&&selDates[i]&&((new Date(`${selDates[i]}T12:00:00`)-new Date(`${selDates[i-1]}T12:00:00`))/86400000>1);if(!p||gap){if(group.length>1)groups.push(group);group=[];}if(p)group.push(p.join(','));});if(group.length>1)groups.push(group);return groups.map(g=>`<polyline class="${cls}" points="${g.join(' ')}"></polyline>`).join('');},dots=(vals,key,cls)=>vals.map((v,i)=>{const p=point(v,i,key);return p?`<circle class="${cls}" cx="${p[0]}" cy="${p[1]}" r="3"><title>${this.esc(selDates[i]||'')}: ${fmt(v,key)}</title></circle>`:'';}).join('');
