    const isLoad=d=>{const x=[d.type,d.category,d.role,d.device_class,d.name,d.friendly_name,d.manufacturer,d.model].filter(Boolean).join(' ').toLowerCase().replaceAll('_',' ');return !/(fronius\s+hybrid|hybrid\s+inverter|inverter|photovoltaic|solar(?:\s+array|\s+system|\s+production|\s+inverter)?|smart\s+meter|grid\s+meter|energy\s+meter|power\s+meter|battery(?:\s+inverter|\s+storage|\s+system)?|converter|gateway)/.test(x);};
    const rows=deaDevices.map(item=>{const base=meta.get(String(item.id))||{},a=item?.periods?.[period]||null;if(!a)return null;const merged={...base,...item,name:base.name||item.name||item.id,type:base.type||item.type||'load'};if(!isLoad(merged))return null;const e=n(a.energy_kwh??a.total_kwh),solar=n(a.solar_kwh),battery=n(a.battery_kwh),grid=n(a.grid_kwh),saved=(solar+battery)*importTariff;return {...merged,energy:e,solar,battery,grid,saved,local:solar+battery,quality:String(a.quality||'Estimated period allocation')};}).filter(Boolean).sort((a,b)=>b.saved-a.saved);
    const registeredEnergy=rows.reduce((s,d)=>s+d.energy,0),registeredLocal=rows.reduce((s,d)=>s+d.local,0),registeredSavings=rows.reduce((s,d)=>s+d.saved,0),measuredRows=rows.filter(d=>/measured/i.test(d.quality)).length,top=rows.find(d=>d.saved>.001)||rows.find(d=>d.local>.001)||rows[0]||null;
    const primary=[['Direct solar',solarValue,'mdi:solar-power-variant'],['Battery support',batteryValue,'mdi:battery-arrow-down-outline'],['Export credit',exportValue,'mdi:transmission-tower-export']].sort((a,b)=>b[1]-a[1])[0];
    const primaryShare=totalPositive>0?primary[1]/totalPositive*100:0,localShare=totalPositive>0?localValue/totalPositive*100:0,exportShare=totalPositive>0?exportValue/totalPositive*100:0;
    const marginalAdvantage=Math.max(0,importTariff-exportTariff),surplusOpportunity=exp>.05&&marginalAdvantage>.001;
    let postureTitle='Balanced financial position',postureText=`${periodTitle} produced ${this.money(totalPositive,currency)} of measured local-energy savings plus export credit against ${this.money(gridCost,currency)} of grid purchase cost.`;
    if(netGrid>.01){postureTitle='Export credit exceeds grid purchase cost';postureText=`Export credit is ${this.money(exportValue,currency)} versus ${this.money(gridCost,currency)} of import cost, leaving a ${this.money(netGrid,currency)} net grid credit before any standing charge.`;}
    else if(netGrid<-.01){postureTitle='Grid purchases exceed export credit';postureText=`Grid purchase cost is ${this.money(gridCost,currency)} versus ${this.money(exportValue,currency)} of export credit. Local solar and battery support avoided a further ${this.money(localValue,currency)} of import value.`;}
    const deviceText=top?`${this.esc(top.name||top.id||'Registered load')} captured the most measured local-energy value among registered loads: ${this.money(top.saved,currency)} from ${this.kwh(top.local)} local supply.`:(rows.length?'Registered-load attribution exists, but no meaningful local-energy saving is measured in this period.':'Registered-load financial attribution is still collecting for this period.');
    const opportunityTitle=surplusOpportunity?'Use more solar locally when practical':(imp>.05?'Reduce purchased energy where practical':'No strong financial action needed');
    const opportunityText=surplusOpportunity?`Each flexible kWh shifted from export to local use is worth about ${this.money(marginalAdvantage,currency)} more at the configured tariffs (${this.money(importTariff,currency)}/kWh import avoided vs ${this.money(exportTariff,currency)}/kWh export credit). Zeus is recommendation-only.`:(imp>.05?`Imported energy cost ${this.money(gridCost,currency)} in this period. Zeus can highlight timing opportunities, but does not control equipment.`:'Configured tariffs and measured flows do not show a strong financial optimization need in this period.');
