    const importTariff=this.numberValue(finance.import_tariff,0),exportTariff=this.numberValue(finance.export_tariff,0),expectedSaving=Math.max(0,(directSolar+batterySupportPotential)*importTariff+expectedExport*exportTariff),confidence=Math.max(0,Math.min(100,this.numberValue(forecast.confidence,forecast.confidence_percent??50)));
    return {forecast,finance,today,battery,recommendation,days,expectedSolar,expectedTomorrow,expectedHome,demandSource,soc,reserve,capacity,usableBattery,batteryHeadroom,directSolar,demandAfterSolar,batterySupportPotential,solarSurplus,batteryChargeOpportunity,localSolarOpportunity,expectedImport,expectedExport,expectedSaving,confidence,currency:finance.currency||this._wizardData?.currency||'CHF'};
