    const trendProgress=`<div class="insight-progress"><div><span>Measured trend history</span><b>${Number(progress.measured_days??days)} / ${Number(progress.required_days??6)} days</b></div><div class="insight-progress-track"><i style="width:${Math.max(0,Math.min(100,Number(progress.percent??Math.min(100,days/6*100))))}%"></i></div><small>${progress.ready?'Supported short-term comparisons are available.':`${Number(progress.remaining_days??Math.max(0,6-days))} more measured day${Number(progress.remaining_days??Math.max(0,6-days))===1?'':'s'} required.`}</small></div>`;
