    const positivesHtml=positives.length?positives.map(item=>`<div class="insight-positive-card"><ha-icon icon="${this.esc(item.icon||'mdi:trophy-outline')}"></ha-icon><div><b>${this.esc(item.title||'Positive outcome')}</b><p>${this.esc(item.detail||'')}</p><small>${item.confidence_percent==null?'Evidence collecting':Number(item.confidence_percent).toFixed(0)+'% confidence'}</small></div></div>`).join(''):'<div class="compact-empty"><ha-icon icon="mdi:medal-outline"></ha-icon><div><b>Positive milestones are collecting</b><p>Zeus will highlight best days, low-import days and strong forecast matches when measured evidence supports them.</p></div></div>';
