class AionEmsZeusCommandCenter extends AionEmsEnergyFlowDashboard {
  constructor(){super();this._dedicatedKiosk=true;this._page='command_center';this._wizardOpen=false;this._setupState='1';this._haShellSnapshot=[];this._kioskHostStyle=null;}
  connectedCallback(){super.connectedCallback();this._page='command_center';this._wizardOpen=false;requestAnimationFrame(()=>this._setHaKioskShell(true));}
  disconnectedCallback(){this._setHaKioskShell(false);super.disconnectedCallback();}
  set hass(hass){this._page='command_center';this._wizardOpen=false;super.hass=hass;}
  _setHaKioskShell(enable){
    if(enable){
      if(this._haShellSnapshot.length)return;
      this._kioskHostStyle=this.getAttribute('style');
      this.style.setProperty('position','fixed','important');
      this.style.setProperty('inset','0','important');
      this.style.setProperty('width','100vw','important');
      this.style.setProperty('max-width','100vw','important');
      this.style.setProperty('height','100vh','important');
      this.style.setProperty('max-height','100vh','important');
      this.style.setProperty('margin','0','important');
      this.style.setProperty('padding','0','important');
      this.style.setProperty('z-index','100','important');
      this.style.setProperty('overflow','hidden','important');
      this.style.setProperty('box-sizing','border-box','important');
      const visit=(root)=>{for(const el of root.querySelectorAll?.('*')||[]){if(el===this||this.contains(el))continue;const tag=(el.tagName||'').toLowerCase();if(['ha-sidebar','ha-menu-button'].includes(tag)||el.getAttribute?.('slot')==='sidebar'){this._haShellSnapshot.push([el,el.getAttribute('style')]);el.style.setProperty('display','none','important');}if(tag==='ha-drawer'){this._haShellSnapshot.push([el,el.getAttribute('style')]);el.style.setProperty('--mdc-drawer-width','0px');el.style.setProperty('--ha-drawer-width','0px');}if(el.shadowRoot)visit(el.shadowRoot);}};
      visit(document);
      document.documentElement.classList.add('aion-zeus-command-center-active');
      document.body.style.overflow='hidden';
    }else{
      for(const [el,style] of this._haShellSnapshot.splice(0)){if(!el?.isConnected)continue;if(style==null)el.removeAttribute('style');else el.setAttribute('style',style);}
      if(this._kioskHostStyle==null)this.removeAttribute('style');else this.setAttribute('style',this._kioskHostStyle);
      this._kioskHostStyle=null;
      document.documentElement.classList.remove('aion-zeus-command-center-active');document.body.style.overflow='';
    }
  }
}
if(!customElements.get('aion-ems-zeus-command-center')) customElements.define('aion-ems-zeus-command-center',AionEmsZeusCommandCenter);


